class Animal {
    String name;
    Animal(String name) { this.name = name; }  // 'this'
    String speak() { return "..."; }
}

class Dog extends Animal {
    String breed;
    Dog(String name, String breed) {
        super(name);              // parent constructor
        this.breed = breed;
    }
    @Override String speak() {
        return super.speak() + " Woof!";  // parent method
    }
}
// No ctor? Java adds default: Dog() { super(); }

